result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/tests/test_cashflow.py", "content": """"Tests for the cash-flow statement builder."""

import csv
import copy
from decimal import Decimal
from pathlib import Path

import pytest

from cashflow import (
    DEFAULT_SECTION_MAP,
    OPENING_CASH,
    SECTION_FINANCING,
    SECTION_INVESTING,
    SECTION_OPERATING,
    SECTIONS,
    UnknownCategoryError,
    build_statement_data,
    verify_reconciliation,
)
from gen import NUM_TRANSACTIONS, generate_transactions
from statement import render_statement

ROOT = Path(__file__).resolve().parent.parent
GOLDEN = Path(__file__).resolve().parent / "golden" / "statement.txt"


def load_fixture_txns():
    """Load the committed CSV fixture (identical to seed-29 generation)."""
    path = ROOT / "tests" / "fixtures" / "transactions.csv"
    with path.open() as fh:
        return [
            {
                "id": int(r["id"]),
                "date": r["date"],
                "category": r["category"],
                "description": r["description"],
                "amount": Decimal(r["amount"]),
            }
            for r in csv.DictReader(fh)
        ]


@pytest.fixture(scope="module")
def txns():
    # CSV fixture must match a fresh in-memory generation of the same seed.
    from_file = load_fixture_txns()
    assert from_file == generate_transactions()
    return from_file


@pytest.fixture(scope="module")
def data(txns):
    return build_statement_data(txns)


# --- 1. Reconciliation identity holds to the cent with Decimal ------------

class TestReconciliation:
    def test_opening_plus_net_change_equals_closing(self, data):
        assert data["opening_cash"] + data["net_change"] == data["closing_cash"]

    def test_closing_is_cent_exact(self, data):
        assert data["closing_cash"].as_tuple().exponent >= -2

    def test_independent_sum_matches_net_change(self, txns, data):
        independent = sum((t["amount"] for t in txns), Decimal("0"))
        assert data["independent_sum"] == independent == data["net_change"]
        assert OPENING_CASH + independent == data["closing_cash"]

    def test_verify_helper(self, data):
        assert verify_reconciliation(data) is True

    def test_verify_detects_tampering(self, data):
        bad = dict(data)
        bad["closing_cash"] = data["closing_cash"] + Decimal("0.01")
        with pytest.raises(AssertionError):
            verify_reconciliation(bad)


# --- 2. Each section subtotal equals the sum of its categories ------------

class TestSectionSubtotals:
    def test_every_section_total_equals_category_sum(self, data):
        for section, payload in data["sections"].items():
            cat_sum = sum(payload["categories"].values(), Decimal("0"))
            assert payload["total"] == cat_sum, section

    def test_all_three_sections_present(self, data):
        assert tuple(data["sections"]) == SECTIONS
        assert set(data["sections"]) == {
            SECTION_OPERATING,
            SECTION_INVESTING,
            SECTION_FINANCING,
        }

    def test_categories_match_mapping_partition(self, txns, data):
        by_section = {s: {} for s in SECTIONS}
        for txn in txns:
            section = DEFAULT_SECTION_MAP[txn["category"]]
            bucket = by_section[section]
            bucket[txn["category"]] = bucket.get(txn["category"], Decimal("0")) + txn["amount"]
        for section in SECTIONS:
            assert data["sections"][section]["categories"] == by_section[section]

    def test_net_change_equals_sum_of_sections(self, data):
        total = sum((data["sections"][s]["total"] for s in SECTIONS), Decimal("0"))
        assert data["net_change"] == total


# --- 3. Unknown category raises with the category name --------------------

class TestUnknownCategory:
    def test_unknown_category_raises_with_name(self):
        txns = [{"category": "bitcoin_mining", "amount": Decimal("-1.00")}]
        with pytest.raises(ValueError) as excinfo:
            build_statement_data(txns)
        assert "bitcoin_mining" in str(excinfo.value)

    def test_specific_exception_type(self):
        txns = [{"category": "mystery", "amount": Decimal("5.00")}]
        with pytest.raises(UnknownCategoryError) as excinfo:
            build_statement_data(txns)
        assert excinfo.value.category == "mystery"
        assert "mystery" in str(excinfo.value)

    def test_raises_before_any_output_is_trusted(self):
        good = [{"category": "rent", "amount": Decimal("-10.00")}]
        bad = [{"category": "nope", "amount": Decimal("1.00")}]
        with pytest.raises(UnknownCategoryError):
            build_statement_data(good + bad)


# --- 4. Invariant: remapping sections never changes net change ------------

class TestRemapInvariant:
    def _net_for(self, txns, section_map):
        d = build_statement_data(txns, section_map=section_map)
        return d["sections"], d["net_change"]

    def test_moving_equipment_to_operating_keeps_net_change(self, txns, data):
        remapped = dict(DEFAULT_SECTION_MAP)
        remapped["equipment_purchase"] = SECTION_OPERATING
        sections2, net2 = self._net_for(txns, remapped)
        assert net2 == data["net_change"]
        assert sections2[SECTION_OPERATING]["total"] != data["sections"][SECTION_OPERATING]["total"]
        assert sections2[SECTION_INVESTING]["total"] == Decimal("0")

    def test_swap_loan_proceeds_between_sections(self, txns, data):
        remapped = dict(DEFAULT_SECTION_MAP)
        remapped["loan_proceeds"] = SECTION_INVESTING
        sections2, net2 = self._net_for(txns, remapped)
        delta_financing = (
            sections2[SECTION_FINANCING]["total"] - data["sections"][SECTION_FINANCING]["total"]
        )
        delta_investing = (
            sections2[SECTION_INVESTING]["total"] - data["sections"][SECTION_INVESTING]["total"]
        )
        assert net2 == data["net_change"]
        assert delta_financing == -delta_investing != 0

    def test_full_permutation_preserves_net_and_closing(self, txns, data):
        # Push every category into Financing.
        everything_financing = {c: SECTION_FINANCING for c in DEFAULT_SECTION_MAP}
        sections2, net2 = self._net_for(txns, everything_financing)
        assert net2 == data["net_change"]
        assert sections2[SECTION_FINANCING]["total"] == data["net_change"]
        assert sections2[SECTION_OPERATING]["total"] == Decimal("0")
        assert sections2[SECTION_INVESTING]["total"] == Decimal("0")


# --- 5. Golden statement fixture, byte-compared ----------------------------

class TestGoldenStatement:
    def test_golden_byte_identical(self, txns):
        rendered = render_statement(build_statement_data(txns))
        expected = GOLDEN.read_bytes()
        assert rendered.encode("utf-8") == expected

    def test_golden_deterministic_across_regeneration(self):
        # Regenerating from scratch (not the CSV fixture) yields identical bytes.
        rendered = render_statement(build_statement_data(generate_transactions()))
        assert rendered.encode("utf-8") == GOLDEN.read_bytes()

    def test_statement_contains_sections_and_footer(self, data):
        text = render_statement(data)
        for needle in ("Operating", "Investing", "Financing", "Opening cash",
                       "Closing cash", "Net change in cash", "Reconciliation OK"):
            assert needle in text


def test_transaction_count():
    assert len(generate_transactions()) == NUM_TRANSACTIONS == 2000
